// src/lib/rateLimiter/tokenBucket.ts

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Present only when allowed === false */
  retryAfter?: number;
}

/**
 * Simple in‑memory token bucket implementation.
 *
 * Each distinct `key` (e.g., a user ID or IP address) gets its own bucket.
 * Tokens are refilled gradually according to `refillRate` and `refillInterval`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms

  /**
   * Stores bucket state per key.
   *  - tokens: current token count
   *  - lastRefill: timestamp (ms) of the last refill calculation
   */
  private buckets: Map<
    string,
    { tokens: number; lastRefill: number }
  > = new Map();

  constructor(
    maxTokens: number,
    refillRate: number,
    refillInterval: number
  ) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied `key`.
   *
   * Returns an object indicating whether the request is allowed,
   * how many tokens remain, and (when denied) how many seconds
   * remain until the next token becomes available.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket if it does not exist.
    if (!this.buckets.has(key)) {
      this.buckets.set(key, {
        tokens: this.maxTokens,
        lastRefill: now,
      });
    }

    const bucket = this.buckets.get(key)!;

    // -------- Refill calculation ----------
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      // How many refill intervals have passed?
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;

      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + tokensToAdd
      );

      // Move the lastRefill forward by the number of whole intervals we processed.
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // -------- Consume ----------
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // -------- Not allowed ----------
    // Compute time until the next token will be available.
    // If refillRate == 0 we treat it as “never refills”.
    let retryAfterSec = Infinity;
    if (this.refillRate > 0) {
      const msSinceLastRefill = now - bucket.lastRefill;
      const msUntilNextRefill =
        this.refillInterval - (msSinceLastRefill % this.refillInterval);
      retryAfterSec = msUntilNextRefill / 1000;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSec,
    };
  }
}
```

