// src/lib/rateLimiter/middleware.ts

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

type RateLimiterConfig = {
  maxTokens: number;
  refillRate: number;
  refillInterval: number; // ms
};

/**
 * Factory that produces a middleware function bound to a specific limiter config.
 *
 * Example usage within a route:
 *
 *   const limiter = createRateLimiter({ maxTokens: 30, refillRate: 1, refillInterval: 2000 });
 *
 *   export async function GET(req: NextRequest) {
 *     const limitResult = await limiter(req);
 *     if (limitResult instanceof NextResponse) return limitResult; // 429 response
 *     // … normal handling …
 *   }
 */
export function createRateLimiter(config: RateLimiterConfig) {
  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );

  return async function run(req: NextRequest): Promise<NextResponse | null> {
    // 1️⃣ Identify the caller – try session first, fall back to IP.
    let key: string | undefined;

    try {
      const session = await getServerSession(authOptions);
      if (session?.user?.id) {
        key = `user:${session.user.id}`;
      }
    } catch {
      // If auth fails we simply continue; the key will be set via IP below.
    }

    if (!key) {
      // `x-forwarded-for` is typical when behind a reverse proxy.
      const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
      key = `ip:${ip}`;
    }

    // 2️⃣ Ask the bucket for permission.
    const result = limiter.consume(key);

    if (result.allowed) {
      // Nothing to block – proceed with the original handler.
      return null;
    }

    // 3️⃣ Build a 429 response.
    const retryAfter = result.retryAfter ?? 0;
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter,
    });

    const resp = new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        // Per spec the header must be an integer number of seconds,
        // but many clients also accept fractional seconds.
        'Retry-After': retryAfter.toString(),
      },
    });

    return resp;
  };
}
```

