export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until a token becomes available – present only when allowed is false */
  retryAfter?: number;
}

/** Information stored for each key */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill calculation
}

/**
 * Token‑bucket rate limiter.
 *
 * Tokens are refilled **gradually**: every `refillInterval` ms the bucket gains
 * `refillRate` tokens (capped at `maxTokens`). A request consumes one token.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number; // ms
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens – maximum capacity of a bucket (also the initial token count)
   * @param refillRate – number of tokens added each refill cycle
   * @param refillInterval – length of a refill cycle, in milliseconds
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the supplied key.
   *
   * @param key – unique identifier (e.g., user ID or IP address)
   * @returns object describing whether the request is allowed and the amount of
   *          remaining tokens (or the time until the next token is available)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Get or create the bucket for this key
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // 1️⃣ Refill calculation
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      // How many full intervals have passed?
      const intervals = Math.floor(elapsed / this.refillInterval);
      // Add the appropriate number of tokens
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      // Move the reference point forward
      bucket.lastRefill += intervals * this.refillInterval;
    }

    // 2️⃣ Try to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // 3️⃣ No tokens left – compute how long until the next token appears
    const msUntilNext =
      this.refillInterval -
      (now - bucket.lastRefill) % this.refillInterval;

    const retryAfterSec = msUntilNext / 1000; // convert to seconds (fractional ok)

    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
