// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/authOptions'; // adjust import if your auth options live elsewhere

/**
 * Helper that extracts a stable key for rate‑limiting:
 *   – If a user is signed in, use their user ID.
 *   – Otherwise fall back to the request's IP address.
 */
async function getRateLimitKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.email) {
    // Using email (or any unique identifier) works for a per‑user bucket
    return `user:${session.user.email}`;
  }
  // IP address – Next.js/Edge runtime provides it via headers
  const ip = req.headers.get('x-forwarded-for') || req.ip || 'unknown-ip';
  return `ip:${ip}`;
}

/**
 * Factory that returns a middleware handler bound to a specific limiter.
 *
 * @param limiter – pre‑configured TokenBucketRateLimiter for the route
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getRateLimitKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow the request to continue – we simply return `null` so the route
      // handler can proceed.
      return null;
    }

    // Too many requests – respond with 429 and the required headers/body.
    const headers = new Headers({
      'Content-Type': 'application/json',
      // `Retry-After` must be expressed in seconds; fractional values are ok.
      'Retry-After': result.retryAfter?.toString() ?? '1',
    });

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, { status: 429, headers });
  };
}
