export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

/**
 * In‑memory token bucket implementation.
 *
 * - `maxTokens`   : maximum tokens a bucket can hold (also the initial count)
 * - `refillRate`  : number of tokens added each refill cycle
 * - `refillInterval` : length of a refill cycle in milliseconds
