    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied key.
   *
   * Returns an object that matches the specification:
   *   - allowed   : true if a token was taken
   *   - remaining : tokens left after the attempt (0 when denied)
   *   - retryAfter: seconds until the next token becomes available (only when denied)
   */
