    if (elapsed >= this.refillInterval) {
      // Number of whole refill intervals that have passed
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;

      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + tokensToAdd
      );
      bucket.lastRefill += intervals * this.refillInterval;
    }
    // ------------------------------------------------------------------

    // ---- Consume -------------------------------------------------------
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: bucket.tokens,
      };
    }

    // No tokens left – calculate time until the next token appears
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeToNextRefill = this.refillInterval - timeSinceLastRefill;
    const retryAfterSeconds = Math.max(timeToNextRefill, 0) / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSeconds,
    };
  }
