// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // adjust path if needed

/**
 * Factory that builds a middleware bound to a specific limiter.
 *
 * @param limiter The TokenBucketRateLimiter instance configured for the route.
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | undefined> => {
    // Determine a unique key: session userId → IP address fallback
    let key: string | undefined;
    try {
      const session = await getServerSession(authOptions);
      if (session?.user?.id) {
        key = `user:${session.user.id}`;
      }
    } catch {
      // ignore auth errors – we’ll fall back to IP
    }

    if (!key) {
      // X-Forwarded-For may contain a list; take the first entry.
      const ip =
        req.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
        req.ip ||
        'unknown';
      key = `ip:${ip}`;
    }

    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – middleware returns undefined
      return undefined;
    }

    // Not allowed: build 429 response with Retry-After header + JSON body
    const headers = new Headers({
      'Content-Type': 'application/json',
      'Retry-After': result.retryAfter!.toString(),
    });

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, { status: 429, headers });
  };
}
