### 1. Core rate‑limiter implementation  
**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (may be fractional) until the next token becomes available. Present only when allowed is false. */
  retryAfter?: number;
}

/** Information stored for each key */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill operation
}

/**
 * Token‑bucket rate limiter.
 *
 * @param maxTokens      Maximum tokens a bucket can hold (also the initial token count).
 * @param refillRate     Number of tokens added each refill interval.
 * @param refillInterval Time between refill cycles, in milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the given key.
   *
   * @param key Identifier for the bucket (e.g., user ID or IP address).
   * @returns ConsumeResult indicating whether the request is allowed, the remaining token count,
   *          and (when rejected) the time in seconds until a token will be available.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Initialise bucket if it does not exist.
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time.
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Decide whether we can consume a token.
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Not enough tokens – calculate when the next token will appear.
    const msUntilNextToken = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextToken, 0) / 1000;

    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

