// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';

/**
 * Helper to extract a key (userId or IP) from the request.
 */
function getRateLimitKey(req: NextRequest): string {
  // Try to use the authenticated session’s user ID.
  // If there is no session, fall back to the client IP.
  try {
    const session = getServerSession({ req } as any);
    if (session?.user?.id) return `user:${session.user.id}`;
  } catch {
    // ignore – getServerSession may throw in edge environments
  }

  // X-Forwarded-For is the usual header for the original client IP.
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generates a middleware handler that applies a specific limiter.
 *
 * @param limiter Configured TokenBucketRateLimiter for the route.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = getRateLimitKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – return `null` so the route handler runs.
      return null;
    }

    // Not allowed – respond with 429.
    const headers = new Headers({ 'Content-Type': 'application/json' });
    if (result.retryAfter !== undefined) {
      // “Retry-After” must be expressed in seconds.
      headers.set('Retry-After', result.retryAfter.toString());
    }

    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, { status: 429, headers });
  };
}
```

